package org.slavicmyths.verify;

import java.util.*;
import java.nio.file.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.projectile.Arrow;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.neoforged.neoforge.gametest.*;
import org.slavicmyths.kurgan.*;
import static org.slavicmyths.kurgan.KurganFighter.*;

@GameTestHolder("slavicmyths_prince277") @PrefixGameTestTemplate(false)
public final class Prince277GameTests {
 private static final class Connection extends net.minecraft.network.Connection {private final io.netty.channel.embedded.EmbeddedChannel c=new io.netty.channel.embedded.EmbeddedChannel();Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public io.netty.channel.Channel channel(){return c;}}
 private static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {Listener(ServerPlayer p){super(p.getServer(),new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener l){}}
 private static ServerPlayer player(GameTestHelper t,Vec3 pos){var p=new ServerPlayer(t.getLevel().getServer(),t.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"Prince277"),ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(GameType.SURVIVAL);p.moveTo(pos);p.setNoGravity(true);p.setHealth(20);try{var f=ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");f.setAccessible(true);f.setInt(p,0);}catch(Exception e){throw new RuntimeException(e);}t.getLevel().addNewPlayer(p);return p;}
 private record Scene(KurganCreature boss,KurganInstance instance,Vec3 center){}
 private static Scene scene(GameTestHelper t,boolean spent){
  for(int x=1;x<78;x++)for(int z=1;z<78;z++)t.setBlock(x,1,z,Blocks.STONE);
  Vec3 center=t.absoluteVec(new Vec3(35.5,2,35.5));var plan=KurganPlan.create(2,277L);var room=plan.rooms.get(plan.finalRoom);var origin=BlockPos.containing(center).offset(-room.x,-room.y-1,-room.z);var instance=new KurganInstance(UUID.randomUUID(),origin,plan);BurialRecords.get(t.getLevel()).instances.put(instance.id,instance);
  var boss=org.slavicmyths.registry.ModEntities.PRINCE.get().create(t.getLevel());boss.moveTo(center);boss.kurgan=instance.id;boss.room=plan.finalRoom;boss.home=BlockPos.containing(center);boss.setPersistenceRequired();var n=new CompoundTag();boss.addAdditionalSaveData(n);n.putBoolean("LimitedSummon",spent);boss.readAdditionalSaveData(n);t.getLevel().addFreshEntity(boss);return new Scene(boss,instance,center);
 }
 private static boolean inside(Scene s){var p=s.boss.blockPosition().subtract(s.instance.origin);return s.instance.plan.rooms.get(s.instance.plan.finalRoom).box().contains(p.getX(),p.getY(),p.getZ());}
 private static Arrow arrow(GameTestHelper t,ServerPlayer p,KurganCreature boss,boolean flight){var a=new Arrow(t.getLevel(),p,new ItemStack(Items.ARROW),null);a.setNoGravity(true);a.setBaseDamage(2);a.setPos(p.position().add(0,1.3,0));var d=boss.position().add(0,1.3,0).subtract(a.position()).normalize().scale(2);a.setDeltaMovement(d);if(flight)t.getLevel().addFreshEntity(a);return a;}
 private static void hit(GameTestHelper t,ServerPlayer p,KurganCreature b){b.invulnerableTime=0;t.assertTrue(b.hurt(t.getLevel().damageSources().arrow(arrow(t,p,b,false),p),4),"arrow damage rejected");}
 private static void trace(GameTestHelper t,String name,Scene s){String line=name+" time="+t.getLevel().getGameTime()+" pos="+s.boss.position()+" hp="+s.boss.getHealth()+" phase="+s.boss.phase()+" action="+s.boss.action()+" target="+(s.boss.getTarget()!=null)+" guard="+s.boss.guarding()+" navDone="+s.boss.getNavigation().isDone()+" inside="+inside(s)+"\n";System.out.print("PRINCE277 "+line);try{Files.createDirectories(Path.of("../docs/implementation/prince277-20261026"));Files.writeString(Path.of("../docs/implementation/prince277-20261026/trace.log"),line,StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception e){throw new RuntimeException(e);}}
 @GameTest(template="arena",timeoutTicks=240) public static void visibleArrowOutsideDoorApproachesBoundary(GameTestHelper t){var s=scene(t,true);var b=s.boss;var p=player(t,s.center.add(24,0,0));arrow(t,p,b,true);for(int tick:new int[]{20,60,120,180})t.runAtTickTime(tick,()->trace(t,"outside24",s));t.runAtTickTime(200,()->{t.assertTrue(b.getHealth()<350,"flying arrow did not hit");t.assertTrue(b.getX()>s.center.x+5,"boss retreats home instead of approaching arena boundary");t.assertTrue(inside(s),"boss escaped arena");p.discard();b.discard();t.succeed();});}
 @GameTest(template="arena",timeoutTicks=90) public static void hiddenArrowRetainsRecentAttacker(GameTestHelper t){var s=scene(t,true);var p=player(t,s.center.add(18,0,0));for(int y=2;y<=6;y++)for(int z=25;z<=45;z++)t.setBlock(43,y,z,Blocks.STONE);hit(t,p,s.boss);t.runAtTickTime(20,()->{trace(t,"hidden20",s);t.assertTrue(s.boss.getTarget()==p,"confirmed hidden attacker forgotten before 120 tick memory");t.assertTrue(p.getHealth()==20,"wall damage");t.assertTrue(inside(s),"wall escape");p.discard();s.boss.discard();t.succeed();});}
 @GameTest(template="arena",timeoutTicks=100) public static void farArrowUsesFiniteExistingGuard(GameTestHelper t){var s=scene(t,true);var p=player(t,s.center.add(39,0,0));hit(t,p,s.boss);var guarded=new int[1];for(int tick=1;tick<=36;tick++)t.runAtTickTime(tick,()->{if(s.boss.guarding())guarded[0]++;});t.runAtTickTime(38,()->{trace(t,"guard39",s);t.assertTrue(guarded[0]>0&&guarded[0]<36,"existing finite guard unused against far arrows: "+guarded[0]);t.assertTrue(s.boss.getHealth()<350,"arrow immunity");p.discard();s.boss.discard();t.succeed();});}
 @GameTest(template="arena",timeoutTicks=100) public static void targetSwitchAndMeleePhases(GameTestHelper t){var s=scene(t,true);var a=player(t,s.center.add(2.5,0,0));var b=player(t,s.center.add(0,0,8));hit(t,a,s.boss);t.runAtTickTime(5,()->{s.boss.setHealth(200);hit(t,b,s.boss);});t.runAtTickTime(9,()->{t.assertTrue(s.boss.phase()==1,"phase1 missing");t.assertTrue(s.boss.getTarget()==b,"latest attacker not selected");b.moveTo(s.center.add(2.5,0,0));s.boss.setHealth(90);});t.runAtTickTime(70,()->{trace(t,"phase2",s);t.assertTrue(s.boss.phase()==2,"phase transitions lost");t.assertTrue(a.getHealth()<20||b.getHealth()<20,"melee repertoire failed to release");t.assertTrue(inside(s),"melee escaped arena");a.discard();b.discard();s.boss.discard();t.succeed();});}
 private static void distance(GameTestHelper t,double range,boolean doorway){var s=scene(t,true);var p=player(t,s.center.add(range,0,0));if(doorway)for(int y=2;y<=6;y++)for(int z=20;z<=50;z++)if(z<34||z>36)t.setBlock(43,y,z,Blocks.STONE);arrow(t,p,s.boss,true);t.runAtTickTime(110,()->{trace(t,"range"+range+" door="+doorway,s);t.assertTrue(s.boss.getHealth()<350,"arrow flight failed");t.assertTrue(s.boss.getX()>s.center.x+4,"no approach");if(doorway)t.assertTrue(s.boss.getX()>t.absolutePos(new BlockPos(43,2,35)).getX()+1,"did not traverse passable doorway");t.assertTrue(inside(s),"arena escape");p.discard();s.boss.discard();t.succeed();});}
 @GameTest(template="arena",timeoutTicks=140) public static void arrow8(GameTestHelper t){distance(t,8,false);}
 @GameTest(template="arena",timeoutTicks=140) public static void arrow16(GameTestHelper t){distance(t,16,false);}
 @GameTest(template="arena",timeoutTicks=140) public static void arrow28ThroughThreeWideDoor(GameTestHelper t){distance(t,28,true);}
 @GameTest(template="arena",timeoutTicks=100) public static void directionalGuardStillTakesArrowDamage(GameTestHelper t){var s=scene(t,true);var p=player(t,s.center.add(39,0,0));hit(t,p,s.boss);boolean[] checked={false};for(int tick=4;tick<36;tick++)t.runAtTickTime(tick,()->{if(!checked[0]&&s.boss.guarding()){s.boss.setYRot(-90);s.boss.setXRot(0);float hp=s.boss.getHealth();hit(t,p,s.boss);float loss=hp-s.boss.getHealth();System.out.println("PRINCE277 guarded damage="+loss);t.assertTrue(loss>0&&loss<1,"guard is immunity or failed directional reduction: "+loss);checked[0]=true;}});t.runAtTickTime(38,()->{t.assertTrue(checked[0],"no guard window");p.discard();s.boss.discard();t.succeed();});}
 @GameTest(template="arena",timeoutTicks=100) public static void summonOnceVictoryAndSavedState(GameTestHelper t){var s=scene(t,false);var p=player(t,s.center.add(24,0,0));var state=new KurganEncounterState();state.prepare(List.of(Kind.PRINCE));state.start();state.slots.getFirst().uuid=s.boss.getUUID();state.alive.add(s.boss.getUUID());s.instance.encounters.put(s.boss.room,state);hit(t,p,s.boss);t.runAtTickTime(60,()->{var summoned=t.getLevel().getEntitiesOfClass(KurganCreature.class,s.boss.getBoundingBox().inflate(45),e->e.getPersistentData().getBoolean("RuneSummoned")&&s.instance.id.equals(e.kurgan));t.assertTrue(summoned.size()==3,"existing three-minion summon changed: "+summoned.size());var n=new CompoundTag();s.boss.addAdditionalSaveData(n);t.assertTrue(n.getBoolean("LimitedSummon"),"summon flag lost");for(var e:summoned)e.discard();s.boss.invulnerableTime=0;s.boss.hurt(t.getLevel().damageSources().playerAttack(p),10000);t.assertTrue(s.instance.bossDefeated&&state.slots.getFirst().defeated,"victory/roster death changed");var restored=KurganInstance.load(s.instance.save());t.assertTrue(restored.bossDefeated&&restored.encounters.get(s.boss.room).slots.getFirst().defeated,"saved victory changed");p.discard();t.succeed();});}
 private static void otherKind(GameTestHelper t,Kind kind,double range,Move expected){var s=scene(t,true);s.boss.discard();var mob=KurganEncounters.type(kind).create(t.getLevel());mob.moveTo(s.center);mob.kurgan=s.instance.id;mob.room=s.instance.plan.finalRoom;mob.home=BlockPos.containing(s.center);t.getLevel().addFreshEntity(mob);var p=player(t,s.center.add(range,0,0));t.runAtTickTime(2,()->hit(t,p,mob));boolean[] seen={false};for(int tick=1;tick<30;tick++)t.runAtTickTime(tick,()->{if(mob.action()==expected)seen[0]=true;});t.runAtTickTime(31,()->{t.assertTrue(seen[0],"other kind lost "+expected);p.discard();mob.discard();t.succeed();});}
 @GameTest(template="arena",timeoutTicks=80) public static void voevodaChargeRegression(GameTestHelper t){otherKind(t,Kind.VOEVODA,8,Move.CHARGE);}
 @GameTest(template="arena",timeoutTicks=80) public static void volkhvBoltRegression(GameTestHelper t){otherKind(t,Kind.VOLKHV,16,Move.BOLT);}
}
